/// <reference types="node" />
import type { StrictUint8Array } from './types'

export function isPoint(publicKey: StrictUint8Array): boolean

export function isPointCompressed(publicKey: StrictUint8Array): boolean

export function isPrivate(privateKey: StrictUint8Array): boolean

export function isXOnlyPoint(xOnly: StrictUint8Array): boolean

export function pointFromScalar(
  privateKey: StrictUint8Array,
  compressed?: boolean
): StrictUint8Array | null

export function pointCompress(
  publicKey: StrictUint8Array,
  compressed?: boolean
): StrictUint8Array | null

export function pointAdd(
  publicKey: StrictUint8Array,
  tweakPoint: StrictUint8Array,
  compressed?: boolean
): StrictUint8Array | null

export function pointAddScalar(
  publicKey: StrictUint8Array,
  tweak: StrictUint8Array,
  compressed?: boolean
): StrictUint8Array | null

export function pointMultiply(
  publicKey: StrictUint8Array,
  tweak: StrictUint8Array,
  compressed?: boolean
): StrictUint8Array | null

export function privateAdd(
  privateKey: StrictUint8Array,
  tweak: StrictUint8Array
): StrictUint8Array | null

export function privateSub(
  privateKey: StrictUint8Array,
  tweak: StrictUint8Array
): StrictUint8Array | null

export function privateNegate(privateKey: StrictUint8Array): StrictUint8Array | null

export interface XOnlyPointAddTweakResult {
  parity: number
  xOnlyPubkey: StrictUint8Array
}

export function xOnlyPointAddTweak(
  xOnly: StrictUint8Array,
  tweak: StrictUint8Array
): XOnlyPointAddTweakResult | null

export interface SignRecoverableResult {
  signature: StrictUint8Array
  recoveryId: number
}

export function signRecoverable(
  hash: StrictUint8Array,
  privateKey: StrictUint8Array,
  extraEntropy?: StrictUint8Array | null
): SignRecoverableResult

export function sign(
  hash: StrictUint8Array,
  privateKey: StrictUint8Array,
  extraEntropy?: StrictUint8Array | null
): StrictUint8Array

export function verify(
  hash: StrictUint8Array,
  publicKey: StrictUint8Array,
  signature: StrictUint8Array
): boolean

export function signSchnorr(
  data: StrictUint8Array,
  privateKey: StrictUint8Array,
  extraEntropy?: StrictUint8Array
): StrictUint8Array

export function verifySchnorr(
  data: StrictUint8Array,
  xOnly: StrictUint8Array,
  signature: StrictUint8Array
): boolean

export function xOnlyPointFromPoint(publicKey: StrictUint8Array): StrictUint8Array

export function xOnlyPointFromScalar(privateKey: StrictUint8Array): StrictUint8Array
